import { scrollToId } from '../lib/motion.js';
import { ALLERGENS } from '../data/menu.js';

const WIDTHS = [640, 1280, 1920];

/** Responsive WebP image generated by scripts/optimize-images.mjs. */
export function Picture({ name, alt, sizes = '100vw', className, priority = false, ...rest }) {
  return (
    <img
      className={className}
      src={`/img/${name}-1280.webp`}
      srcSet={WIDTHS.map((w) => `/img/${name}-${w}.webp ${w}w`).join(', ')}
      sizes={sizes}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding="async"
      {...rest}
    />
  );
}

/** In-page link that uses the smooth scroller and keeps a real href. */
export function AnchorLink({ to, children, onNavigate, ...rest }) {
  return (
    <a
      href={`#${to}`}
      onClick={(e) => {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
        e.preventDefault();
        onNavigate?.();
        scrollToId(to);
      }}
      {...rest}
    >
      {children}
    </a>
  );
}

/** Gold ornamental divider: a lozenge flanked by fading rules. */
export function Ornament({ className = '' }) {
  return (
    <span className={`ornament ${className}`} aria-hidden="true">
      <span className="ornament__line" />
      <svg viewBox="0 0 24 24" width="14" height="14">
        <path d="M12 1 L23 12 L12 23 L1 12 Z" fill="none" stroke="currentColor" strokeWidth="1.4" />
        <path d="M12 7 L17 12 L12 17 L7 12 Z" fill="currentColor" />
      </svg>
      <span className="ornament__line" />
    </span>
  );
}

/** Section heading with a Chinese seal-style eyebrow. */
export function SectionTitle({ eyebrow, zh, title, children, id, as: Tag = 'h2', align = 'center' }) {
  return (
    <header className={`section-title section-title--${align}`} data-reveal>
      {zh && (
        <span className="section-title__zh" lang="zh-Hant" aria-hidden="true">
          {zh}
        </span>
      )}
      {eyebrow && <p className="eyebrow">{eyebrow}</p>}
      <Tag className="section-title__h" id={id}>
        {title}
      </Tag>
      <Ornament />
      {children && <div className="section-title__lead">{children}</div>}
    </header>
  );
}

/** Price with an accessible label. `null` prices show a clear placeholder. */
export function Price({ value, className = '' }) {
  if (value == null) {
    return <span className={`price price--missing ${className}`}>Precio a consultar</span>;
  }
  return (
    <span className={`price ${className}`} aria-label={`${value} euros`}>
      {value}
      <span className="price__cur" aria-hidden="true">
        €
      </span>
    </span>
  );
}

export function Allergens({ list }) {
  if (!list?.length) return null;
  return (
    <ul className="allergens" aria-label="Alérgenos">
      {list.map((n) => (
        <li key={n} className={`allergen allergen--${n}`} title={ALLERGENS[n]}>
          <span aria-hidden="true">{n}</span>
          <span className="sr-only">{ALLERGENS[n]}</span>
        </li>
      ))}
    </ul>
  );
}

